+// The audit trail of requests that changed data.
+
+/** Appends an audit entry (time, key name, method, path, status). */
+export function recordAudit(store, { at, name, method, path, status }) {
+  store.data.audit.push({ id: store.nextId("audit"), at, name, method, path, status });
+}
+
+/** All audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
