+// API keys and roles. Roles: viewer reads, cook also does kitchen work,
+// manager does everything.
+import { AppError } from "../errors.js";
+
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+/** The api key record for an `Authorization: Bearer <key>` header, or throws unauthorized. */
+export function authenticate(store, header) {
+  const m = /^Bearer (.+)$/.exec(typeof header === "string" ? header.trim() : "");
+  const key = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1].trim());
+  if (!key) throw new AppError("unauthorized");
+  return key;
+}
+
+/** Throws forbidden unless `role` may call `method` on the route `pattern`. */
+export function authorize(role, method, pattern) {
+  if (role === "manager") return;
+  if (pattern === "/audit") throw new AppError("forbidden");
+  if (method === "GET") {
+    if (role === "viewer" || role === "cook") return;
+  } else if (role === "cook" && COOK_ROUTES.has(`${method} ${pattern}`)) return;
+  throw new AppError("forbidden");
+}
