diff --git a/tests/auth.test.js b/tests/auth.test.js
new file mode 100644
index 0000000..6ac310c
--- /dev/null
+++ b/tests/auth.test.js
@@ -0,0 +1,46 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { createApp } from "../src/http/server.js";
+import { NOW, as, fresh } from "./helpers.js";
+
+const raw = () => {
+  const store = fresh();
+  return { store, handle: createApp(store, { clock: () => NOW }) };
+};
+
+test("missing or unknown keys are 401", async () => {
+  const { handle } = raw();
+  const a = await handle({ path: "/items" });
+  assert.equal(a.status, 401);
+  assert.equal(a.body.error.code, "unauthorized");
+  const b = await handle({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(b.status, 401);
+});
+
+test("viewer reads only, cook cooks, manager does all", async () => {
+  const { handle } = raw();
+  const viewer = as("viewer", handle);
+  const cook = as("cook", handle);
+  const manager = as("manager", handle);
+  assert.equal((await viewer({ path: "/items" })).status, 200);
+  const denied = await viewer({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(denied.status, 403);
+  assert.equal(denied.body.error.code, "forbidden");
+  assert.equal((await cook({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await cook({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 403);
+  assert.equal((await manager({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 201);
+  assert.equal((await cook({ path: "/audit" })).status, 403);
+});
+
+test("changes are audited, newest first, for managers", async () => {
+  const { handle } = raw();
+  await as("cook", handle)({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await as("viewer", handle)({ method: "POST", path: "/temperatures", body: {} });
+  const log = (await as("manager", handle)({ path: "/audit" })).body;
+  assert.equal(log.length, 2);
+  assert.deepEqual(log.map((e) => [e.name, e.method, e.path, e.status]), [
+    ["viewer", "POST", "/temperatures", 403],
+    ["cook", "POST", "/recipes/1/cook", 200],
+  ]);
+  assert.equal(log[1].at, new Date(NOW).toISOString());
+});
